class IncorrectBtsType(Exception):
    """
    Raised when bts type was neither GNB nor ENB
    """
    pass


class FaultSignatureFieldEmpty(Exception):
    """
    Raised when field in fault_signature contains no info
    """
    pass


class FaultIdNotProvided(Exception):
    """
    Raised when fault_id was not provided
    """
    pass


class AlarmIdNotProvided(Exception):
    """
    Raised when alarm_id was not provided
    """
    pass


class FaultIdNotDefinedInDatabase(Exception):
    """
    Raised when fault_id was not defined in database
    """
    pass
